// Acquisition driver for the angular-tiny-translator-v0-12-0 ingest.
// Consent: VL-LEGACY-CORPUS-2026-08-10. Network mode must be `consented`.
// GET only, no credentials, no redirects followed, no retries, identity encoding.
// Every accepted response is ledgered with byte count and sha256.
import { createHash } from 'node:crypto';
import { mkdirSync, writeFileSync, appendFileSync } from 'node:fs';
import { resolve } from 'node:path';

const REPO = 'martinroob/tiny-translator';
const TAG = 'v0.12.0';
const EXPECTED_COMMIT = '08dcacf6a41d5a6f6dfbc71d858adcdc4c85691a';
const SLUG = 'angular-tiny-translator-v0-12-0';

const root = resolve(process.argv[2]);
const evidenceDir = resolve(process.argv[3]);
const cacheDir = resolve(root, 'archive');
mkdirSync(cacheDir, { recursive: true });
const ledger = resolve(evidenceDir, 'probe-ledger.ndjson');

if (process.env.VERSIONLESS_NETWORK_MODE !== 'consented') {
  throw new Error('VERSIONLESS_NETWORK_MODE must be `consented` for this acquisition');
}

const caps = {
  maximumAcceptedResponses: 8,
  maximumApiResponseBytes: 16777216,
  maximumArchiveBytes: 134217728,
  maximumAggregateWireBytes: 314572800,
};
let accepted = 0;
let aggregateBytes = 0;
const requests = [];

async function get(url, phase, extra = {}) {
  if (accepted >= caps.maximumAcceptedResponses) throw new Error('response cap exceeded');
  const res = await fetch(url, {
    method: 'GET',
    redirect: 'error',
    headers: {
      accept: extra.accept ?? 'application/vnd.github+json',
      'accept-encoding': 'identity',
      'user-agent': 'versionless-legacy-corpus-ingest',
    },
  });
  const buf = Buffer.from(await res.arrayBuffer());
  if (res.status !== 200) throw new Error(`non-200 ${res.status} for ${url}`);
  const limit = extra.archive ? caps.maximumArchiveBytes : caps.maximumApiResponseBytes;
  if (buf.byteLength > limit) throw new Error('byte cap exceeded');
  aggregateBytes += buf.byteLength;
  if (aggregateBytes > caps.maximumAggregateWireBytes) throw new Error('aggregate cap exceeded');
  accepted += 1;
  const sha256 = createHash('sha256').update(buf).digest('hex');
  const record = {
    at: new Date().toISOString(),
    phase,
    method: 'GET',
    url,
    status: res.status,
    bytes: buf.byteLength,
    sha256,
    ...(extra.stream ? { stream: extra.stream } : {}),
  };
  appendFileSync(ledger, JSON.stringify(record) + '\n');
  requests.push({ endpoint: url, status: res.status, bytes: buf.byteLength, sha256, ...(extra.stream ? { stream: extra.stream } : {}) });
  return { buf, sha256, res };
}

const out = {};

const repoRes = await get(`https://api.github.com/repos/${REPO}`, 'admission-gate-probe');
const repoJson = JSON.parse(repoRes.buf.toString('utf8'));
out.repository = {
  id: repoJson.id,
  fullName: repoJson.full_name,
  private: repoJson.private,
  archived: repoJson.archived,
  disabled: repoJson.disabled,
  fork: repoJson.fork,
  stargazers: repoJson.stargazers_count,
  forks: repoJson.forks_count,
  openIssues: repoJson.open_issues_count,
  createdAt: repoJson.created_at,
  pushedAt: repoJson.pushed_at,
  defaultBranch: repoJson.default_branch,
  license: repoJson.license ? { key: repoJson.license.key, spdx: repoJson.license.spdx_id, name: repoJson.license.name } : null,
  description: repoJson.description,
  homepage: repoJson.homepage,
  size: repoJson.size,
  responseBytes: repoRes.buf.byteLength,
  responseSha256: repoRes.sha256,
};

const refRes = await get(`https://api.github.com/repos/${REPO}/git/ref/tags/${TAG}`, 'admission-gate-probe');
const refJson = JSON.parse(refRes.buf.toString('utf8'));
out.ref = { ref: refJson.ref, objectType: refJson.object.type, objectSha: refJson.object.sha };

let commitSha;
let tagMeta = null;
if (refJson.object.type === 'tag') {
  const tagRes = await get(`https://api.github.com/repos/${REPO}/git/tags/${refJson.object.sha}`, 'admission-gate-probe');
  const tagJson = JSON.parse(tagRes.buf.toString('utf8'));
  tagMeta = {
    tagObjectSha: tagJson.sha,
    tag: tagJson.tag,
    message: tagJson.message,
    taggerDate: tagJson.tagger?.date ?? null,
    verified: tagJson.verification?.verified ?? false,
    verificationReason: tagJson.verification?.reason ?? null,
  };
  commitSha = tagJson.object.sha;
} else {
  commitSha = refJson.object.sha;
}
out.tag = tagMeta;
out.commitShaFromRef = commitSha;
out.expectedCommitSha = EXPECTED_COMMIT;
out.expectedCommitShaConfirmedFromWire = commitSha === EXPECTED_COMMIT;
if (!out.expectedCommitShaConfirmedFromWire) throw new Error(`commit sha mismatch: wire ${commitSha} vs expected ${EXPECTED_COMMIT}`);

const commitRes = await get(`https://api.github.com/repos/${REPO}/git/commits/${commitSha}`, 'admission-gate-probe');
const commitJson = JSON.parse(commitRes.buf.toString('utf8'));
out.commit = {
  sha: commitJson.sha,
  date: commitJson.committer?.date ?? null,
  authorDate: commitJson.author?.date ?? null,
  message: commitJson.message,
  treeSha: commitJson.tree.sha,
  parents: commitJson.parents.map((p) => p.sha),
  verified: commitJson.verification?.verified ?? false,
  verificationReason: commitJson.verification?.reason ?? null,
};

const treeRes = await get(`https://api.github.com/repos/${REPO}/git/trees/${commitJson.tree.sha}?recursive=1`, 'admission-gate-probe');
const treeJson = JSON.parse(treeRes.buf.toString('utf8'));
writeFileSync(resolve(evidenceDir, 'probe-tree.json'), JSON.stringify(treeJson, null, 1));
out.tree = {
  sha: treeJson.sha,
  truncated: treeJson.truncated,
  entries: treeJson.tree.length,
  blobs: treeJson.tree.filter((e) => e.type === 'blob').length,
  directories: treeJson.tree.filter((e) => e.type === 'tree').length,
  gitlinks: treeJson.tree.filter((e) => e.type === 'commit').length,
  symlinks: treeJson.tree.filter((e) => e.mode === '120000').length,
  executableBlobs: treeJson.tree.filter((e) => e.mode === '100755').length,
};

const archiveUrl = `https://codeload.github.com/${REPO}/tar.gz/${commitSha}`;
const a1 = await get(archiveUrl, 'source-acquisition', { archive: true, stream: 1, accept: 'application/gzip' });
writeFileSync(resolve(cacheDir, 'archive-1.tar.gz'), a1.buf);
const a2 = await get(archiveUrl, 'source-acquisition', { archive: true, stream: 2, accept: 'application/gzip' });
writeFileSync(resolve(cacheDir, 'archive-2.tar.gz'), a2.buf);

out.archive = {
  endpoint: archiveUrl,
  bytes: a1.buf.byteLength,
  sha256: a1.sha256,
  streamsFetched: 2,
  streamsByteIdentical: a1.sha256 === a2.sha256 && a1.buf.byteLength === a2.buf.byteLength,
};
if (!out.archive.streamsByteIdentical) throw new Error('archive double-fetch is not byte-identical');

out.transaction = {
  attemptedRequests: requests.length,
  acceptedResponses: accepted,
  acceptedWireBytes: aggregateBytes,
  redirectsObserved: 0,
  setCookiesUsed: 0,
  retries: 0,
  credentialsSent: 0,
};
out.requests = requests;
out.slug = SLUG;
writeFileSync(resolve(evidenceDir, 'drivers', 'acquire-output.json'), JSON.stringify(out, null, 2));
console.log(JSON.stringify({ ok: true, commitSha, treeSha: out.tree.sha, archiveSha256: out.archive.sha256, bytes: out.archive.bytes, entries: out.tree.entries }, null, 2));

