// Blob-level reconciliation of the extracted archive against the recursive git tree
// at the pinned revision, plus a byte scan for git-lfs pointers. No network.
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync, readdirSync, statSync, lstatSync, readlinkSync } from 'node:fs';
import { resolve, relative, join } from 'node:path';

const extracted = resolve(process.argv[2]); // .../verify/extracted
const evidenceDir = resolve(process.argv[3]);
const tree = JSON.parse(readFileSync(resolve(evidenceDir, 'probe-tree.json'), 'utf8'));

const roots = readdirSync(extracted);
if (roots.length !== 1) throw new Error(`expected a single archive root, saw ${roots.length}`);
const archiveRoot = roots[0];
const base = join(extracted, archiveRoot);

function walk(dir, acc = { files: [], dirs: [], special: [], symlinks: [] }) {
  for (const name of readdirSync(dir)) {
    const full = join(dir, name);
    const st = lstatSync(full);
    if (st.isSymbolicLink()) acc.symlinks.push(full);
    else if (st.isDirectory()) {
      acc.dirs.push(full);
      walk(full, acc);
    } else if (st.isFile()) acc.files.push(full);
    else acc.special.push(full);
  }
  return acc;
}
const found = walk(base);

function gitBlobSha(buf) {
  return createHash('sha1').update(Buffer.concat([Buffer.from(`blob ${buf.byteLength}\0`), buf])).digest('hex');
}

const treeBlobs = new Map();
for (const e of tree.tree) if (e.type === 'blob') treeBlobs.set(e.path, e);

const archiveBlobs = new Map();
const lfsPointers = [];
const bigFiles = [];
let totalBytes = 0;
for (const full of found.files) {
  const rel = relative(base, full);
  const buf = readFileSync(full);
  totalBytes += buf.byteLength;
  archiveBlobs.set(rel, { sha: gitBlobSha(buf), bytes: buf.byteLength, sha256: createHash('sha256').update(buf).digest('hex') });
  const head = buf.subarray(0, 200).toString('utf8');
  if (head.startsWith('version https://git-lfs.github.com/spec/')) lfsPointers.push(rel);
  if (buf.byteLength > 1024 * 512) bigFiles.push({ path: rel, bytes: buf.byteLength });
}
for (const full of found.symlinks) {
  const rel = relative(base, full);
  const buf = Buffer.from(readlinkSync(full), 'utf8');
  archiveBlobs.set(rel, { sha: gitBlobSha(buf), bytes: buf.byteLength, sha256: createHash('sha256').update(buf).digest('hex'), symlink: true });
}

const missing = [...treeBlobs.keys()].filter((p) => !archiveBlobs.has(p));
const extra = [...archiveBlobs.keys()].filter((p) => !treeBlobs.has(p));
const mismatched = [];
for (const [p, e] of treeBlobs) {
  const a = archiveBlobs.get(p);
  if (a && a.sha !== e.sha) mismatched.push({ path: p, gitSha: e.sha, archiveSha: a.sha });
}

const normalizedManifest = [...archiveBlobs.keys()].sort().map((p) => `${archiveBlobs.get(p).sha}  ${p}`).join('\n') + '\n';
const normalizedManifestSha256 = createHash('sha256').update(normalizedManifest).digest('hex');

const traversal = [...archiveBlobs.keys()].filter((p) => p.split('/').includes('..'));
const absolute = [...archiveBlobs.keys()].filter((p) => p.startsWith('/'));

const record = {
  schemaVersion: 'versionless.legacy-corpus-reconciliation.v1',
  slug: 'angular-tiny-translator-v0-12-0',
  archiveRoot,
  gitBlobs: treeBlobs.size,
  gitTrees: tree.tree.filter((e) => e.type === 'tree').length,
  gitGitlinks: tree.tree.filter((e) => e.type === 'commit').length,
  archiveFiles: found.files.length,
  archiveDirectories: found.dirs.length,
  archiveSymlinks: found.symlinks.length,
  specialEntries: found.special.length,
  pathTraversalEntries: traversal.length,
  absolutePathEntries: absolute.length,
  missingFiles: missing.length,
  extraFiles: extra.length,
  mismatchedBlobs: mismatched.length,
  missingList: missing,
  extraList: extra,
  mismatchedList: mismatched,
  extractedBytes: totalBytes,
  normalizedManifestSha256,
  lfs: {
    pointerFilesFound: lfsPointers.length,
    pointerFileList: lfsPointers,
    gitattributesPresent: treeBlobs.has('.gitattributes'),
    method: 'Every regular file in the extracted archive was read in full and its first 200 bytes tested against the git-lfs pointer preamble `version https://git-lfs.github.com/spec/`.',
  },
  largestFiles: bigFiles.sort((a, b) => b.bytes - a.bytes).slice(0, 10),
  method: 'Every regular file and symlink in the extracted archive was hashed as a git blob object and compared to the sha recorded for the same path in the recursive git tree at the pinned revision.',
};
writeFileSync(resolve(evidenceDir, 'reconciliation.json'), JSON.stringify(record, null, 1) + '\n');
writeFileSync(resolve(evidenceDir, 'drivers', 'reconcile-output.json'), JSON.stringify({ archiveRoot, blobIndex: Object.fromEntries(archiveBlobs) }, null, 1));
console.log(JSON.stringify({ archiveRoot, gitBlobs: treeBlobs.size, archiveFiles: found.files.length, missing: missing.length, extra: extra.length, mismatched: mismatched.length, lfsPointers: lfsPointers.length, normalizedManifestSha256 }, null, 2));

