// Offline fact collection over the reconciled source and the baseline cell.
// Emits drivers/facts-output.json; no network.
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync, existsSync, readdirSync, statSync } from 'node:fs';
import { resolve, join } from 'node:path';

const evidenceDir = resolve(process.argv[2]);
const src = resolve(process.argv[3]);
const app = resolve(process.argv[4]);
const tree = JSON.parse(readFileSync(resolve(evidenceDir, 'probe-tree.json'), 'utf8'));
const byPath = new Map(tree.tree.map((e) => [e.path, e]));

function fileFacts(rel) {
  const buf = readFileSync(join(src, rel));
  const e = byPath.get(rel);
  return { path: rel, gitBlobSha: e?.sha ?? null, bytes: buf.byteLength, sha256: createHash('sha256').update(buf).digest('hex') };
}

const out = {};
out.keyFiles = ['LICENSE', 'package.json', 'yarn.lock', '.angular-cli.json', 'README.md', 'Changelog.md', 'src/ngsw-config.json', 'cert.pem', 'key.pem', 'xliffmerge.json', 'tsconfig.json', 'Dockerfile'].filter((p) => existsSync(join(src, p))).map(fileFacts);

const pkg = JSON.parse(readFileSync(join(src, 'package.json'), 'utf8'));
out.manifest = {
  name: pkg.name,
  version: pkg.version,
  license: pkg.license,
  private: pkg.private ?? false,
  engines: pkg.engines ?? null,
  dependencyCount: Object.keys(pkg.dependencies).length,
  devDependencyCount: Object.keys(pkg.devDependencies).length,
  scripts: Object.keys(pkg.scripts),
  dependencies: pkg.dependencies,
  devDependencies: pkg.devDependencies,
};

// yarn.lock statistics
const lock = readFileSync(join(src, 'yarn.lock'), 'utf8');
const lockLines = lock.split('\n');
const specHeaders = lockLines.filter((l) => /^[^\s#].*:$/.test(l));
const versions = lockLines.filter((l) => /^ {2}version /.test(l));
const resolved = lockLines.filter((l) => /^ {2}resolved /.test(l));
const withSha1Fragment = resolved.filter((l) => /#[0-9a-f]{40}"?$/.test(l));
const integrity = lockLines.filter((l) => /^ {2}integrity /.test(l));
const hosts = {};
for (const l of resolved) {
  const m = l.match(/resolved "(https?:\/\/[^/]+)/);
  if (m) hosts[m[1]] = (hosts[m[1]] ?? 0) + 1;
}
const names = new Set();
for (const h of specHeaders) {
  for (const spec of h.slice(0, -1).split(', ')) {
    const s = spec.replace(/^"|"$/g, '');
    const at = s.lastIndexOf('@');
    names.add(s.slice(0, at));
  }
}
out.lock = {
  file: 'yarn.lock',
  format: lockLines[1]?.trim() ?? null,
  bytes: Buffer.byteLength(lock),
  specHeaders: specHeaders.length,
  entriesWithVersion: versions.length,
  entriesWithResolvedUrl: resolved.length,
  entriesWithSha1UrlFragment: withSha1Fragment.length,
  entriesWithSubresourceIntegrityField: integrity.length,
  distinctPackageNames: names.size,
  registryHosts: hosts,
};

// resolved versions in the baseline cell
function installed(name) {
  const p = join(app, 'node_modules', name, 'package.json');
  if (!existsSync(p)) return null;
  const j = JSON.parse(readFileSync(p, 'utf8'));
  return j.version;
}
out.resolvedInBaselineCell = Object.fromEntries(
  ['@angular/core', '@angular/common', '@angular/cli', '@angular/compiler', '@angular/compiler-cli', '@angular/material', '@angular/cdk', '@angular/flex-layout', '@angular/service-worker', '@angular/router', 'typescript', 'rxjs', 'zone.js', 'webpack', 'node-sass', 'ngx-i18nsupport-lib', 'ngx-i18nsupport', 'file-saver', 'core-js', 'karma', 'protractor', 'tslint', 'codelyzer'].map((n) => [n, installed(n)]),
);
const cliPkg = JSON.parse(readFileSync(join(app, 'node_modules', '@angular/cli', 'package.json'), 'utf8'));
out.angularCliEngines = cliPkg.engines ?? null;

// installed package census
function countPackages(dir, depth = 0) {
  let n = 0;
  if (!existsSync(dir)) return 0;
  for (const name of readdirSync(dir)) {
    if (name.startsWith('.')) continue;
    const full = join(dir, name);
    if (!statSync(full).isDirectory()) continue;
    if (name.startsWith('@')) {
      for (const scoped of readdirSync(full)) {
        n += 1;
        n += countPackages(join(full, scoped, 'node_modules'), depth + 1);
      }
    } else {
      n += 1;
      n += countPackages(join(full, 'node_modules'), depth + 1);
    }
  }
  return n;
}
out.installedPackageDirectories = countPackages(join(app, 'node_modules'));

// source census
function walk(dir, acc = []) {
  for (const name of readdirSync(dir)) {
    const full = join(dir, name);
    const st = statSync(full);
    if (st.isDirectory()) walk(full, acc);
    else acc.push(full);
  }
  return acc;
}
const srcFiles = walk(join(src, 'src'));
const e2eFiles = existsSync(join(src, 'e2e')) ? walk(join(src, 'e2e')) : [];
out.census = {
  treeBlobs: tree.tree.filter((e) => e.type === 'blob').length,
  filesUnderSrc: srcFiles.length,
  typescriptFiles: srcFiles.filter((f) => f.endsWith('.ts')).length,
  specFiles: srcFiles.filter((f) => f.endsWith('.spec.ts')).length,
  nonSpecTypescriptFiles: srcFiles.filter((f) => f.endsWith('.ts') && !f.endsWith('.spec.ts')).length,
  componentTemplates: srcFiles.filter((f) => f.endsWith('.html')).length,
  styleFiles: srcFiles.filter((f) => f.endsWith('.css') || f.endsWith('.scss')).length,
  e2eFiles: e2eFiles.length,
  xliffFixtures: srcFiles.filter((f) => f.endsWith('.xlf')).length,
  nonSpecTypescriptBytes: srcFiles.filter((f) => f.endsWith('.ts') && !f.endsWith('.spec.ts')).reduce((a, f) => a + statSync(f).size, 0),
  specTypescriptBytes: srcFiles.filter((f) => f.endsWith('.spec.ts')).reduce((a, f) => a + statSync(f).size, 0),
};

// dist artifacts from the baseline builds
function distFacts(rel) {
  const d = join(app, rel);
  if (!existsSync(d)) return null;
  const files = walk(d);
  return {
    path: rel,
    files: files.length,
    bytes: files.reduce((a, f) => a + statSync(f).size, 0),
    entryFiles: files.map((f) => f.slice(d.length + 1)).filter((f) => /^(index\.html|ngsw\.json|ngsw-worker\.js|3rdpartylicenses\.txt|(inline|main|polyfills|styles)\..*\.bundle\.(js|css))$/.test(f)).sort(),
  };
}
out.dist = { baseline: distFacts('dist/baseline'), en: distFacts('dist/en') };

writeFileSync(resolve(evidenceDir, 'drivers', 'facts-output.json'), JSON.stringify(out, null, 1));
console.log(JSON.stringify({ lock: out.lock, resolved: out.resolvedInBaselineCell, census: out.census, packages: out.installedPackageDirectories, dist: out.dist, engines: out.angularCliEngines }, null, 1));

