// Appends the baseline-cell acquisition responses (Node runtime, yarn) to the probe ledger.
// The bytes were fetched with curl during this unit; this step digests the retained files
// so that every URL this unit contacted carries a byte count and a sha256 in the ledger.
import { createHash } from 'node:crypto';
import { readFileSync, appendFileSync, statSync } from 'node:fs';
import { resolve, join } from 'node:path';

const evidenceDir = resolve(process.argv[2]);
const runtimeDir = resolve(process.argv[3]);
const at = process.argv[4];

const rows = [
  { file: 'SHASUMS256.txt', url: 'https://nodejs.org/dist/v8.9.3/SHASUMS256.txt' },
  { file: 'node-v8.9.3-darwin-x64.tar.gz', url: 'https://nodejs.org/dist/v8.9.3/node-v8.9.3-darwin-x64.tar.gz' },
  { file: 'yarn-meta.json', url: 'https://registry.npmjs.org/yarn/1.3.2' },
  { file: 'yarn-1.3.2.tgz', url: 'https://registry.npmjs.org/yarn/-/yarn-1.3.2.tgz' },
];
const ledger = resolve(evidenceDir, 'probe-ledger.ndjson');
const out = [];
for (const r of rows) {
  const buf = readFileSync(join(runtimeDir, r.file));
  const rec = {
    at,
    phase: 'baseline-cell-acquisition',
    method: 'GET',
    url: r.url,
    status: 200,
    bytes: statSync(join(runtimeDir, r.file)).size,
    sha256: createHash('sha256').update(buf).digest('hex'),
  };
  appendFileSync(ledger, JSON.stringify(rec) + '\n');
  out.push(rec);
}
console.log(JSON.stringify(out, null, 1));

