// Validates that every published record in this ingest parses, and that no NDJSON line is malformed.
import { readFileSync, readdirSync } from 'node:fs';
import { resolve, join } from 'node:path';

const evidenceDir = resolve(process.argv[2]);
const fixtureDir = resolve(process.argv[3]);
const bad = [];
const ok = [];
function check(dir) {
  for (const name of readdirSync(dir)) {
    const full = join(dir, name);
    if (name.endsWith('.json')) {
      try {
        JSON.parse(readFileSync(full, 'utf8'));
        ok.push(name);
      } catch (e) {
        bad.push({ file: name, error: e.message });
      }
    } else if (name.endsWith('.ndjson')) {
      const lines = readFileSync(full, 'utf8').trim().split('\n');
      lines.forEach((l, i) => {
        try {
          JSON.parse(l);
        } catch (e) {
          bad.push({ file: name, line: i + 1, error: e.message });
        }
      });
      ok.push(`${name} (${lines.length} lines)`);
    }
  }
}
check(evidenceDir);
check(join(evidenceDir, 'drivers'));
check(fixtureDir);
console.log(JSON.stringify({ ok, bad }, null, 1));
process.exit(bad.length === 0 ? 0 : 1);
